  ["TRIVIAL_QUEST_DISPLAY"] = { "|cff000000%s (basso livello)|r", 0x26fd5f79, "." },
  ["TTS_CONFIRM_SAVE_SETTINGS"] = { "Vuoi che questo personaggio usi le impostazioni di sintesi vocale salvate su questo computer? Se hai effettuato l'accesso da un computer diverso, questo salvataggio sovrascriverà qualsiasi impostazione precedente.", 0x1f1d7c30, "." },
  ["TURN_IN_ITEMS"] = { "Oggetti richiesti:", 0xbbe9aa89, "." },
  ["TUTORIAL17"] = { "Puoi rispondere al personaggio premendo il tasto R o digitando /w <personaggio>, seguito poi dal messaggio.", 0x7a302632, "." },
  ["TUTORIAL18"] = { "Puoi invitare un altro giocatore nel tuo gruppo cliccando col |cffffd200pulsante destro|r sul suo ritratto e selezionando |cffffd200Invita|r dal menu a comparsa.|n|nPuoi abbandonare un gruppo cliccando col pulsante destro sul tuo ritratto e selezionando l'opzione Abbandona gruppo.", 0x7814ee3b, "." },
  ["TUTORIAL22"] = { "Se ti è piaciuto giocare con un altro giocatore, aggiungilo al tuo elenco amici! Clicca sul pulsante |cffffd200Sociale|r e aggiungilo agli amici.|n|nPuoi aggiungere agli amici solo giocatori del tuo reame.", 0xf6dcc955, "." },
  ["TUTORIAL27"] = { "Se ti avventuri in acque profonde o inesplorate, compare la barra della fatica. Se diventi completamente affaticato, inizierai ad affogare.", 0xcbd572f2, "." },
  ["TUTORIAL28"] = { "Nuotare è come camminare, tranne che puoi inclinarti verso l'alto e il basso tenendo premuto il |cffffd200pulsante destro|r e spostando lo sguardo nella direzione in cui vuoi procedere.", 0xc5c14f6c, "." },
  ["TUTORIAL37"] = { "Uno dei tuoi oggetti si è rotto! L'icona del personaggio sotto la minimappa mostra l'oggetto rotto in rosso.|n|nTrova un mercante capace di riparare l'oggetto. Fin quando non lo farai, non otterrai alcun beneficio dall'oggetto rotto.", 0xdd6f4359, "." },
  ["TUTORIAL46"] = { "Ti sei unito a un gruppo di incursione: è un gruppo con un limite massimo di 40 membri, anche se normalmente sono 10 o 25. I gruppi di incursione sono necessari per entrare nelle istanze più impegnative o per sconfiggere i nemici più potenti, solitamente ad alti livelli.|n|n|cffff2020Quando sei in un gruppo di incursione, non otterrai il riconoscimento per il completamento della maggior parte delle missioni. Per abbandonare un gruppo di incursione, clicca col pulsante destro sul tuo ritratto e seleziona Abbandona gruppo.|r", 0x4bb17c25, "." },
  ["TUTORIAL52"] = { "Congratulazioni, hai ricevuto la tua prima mascotte. Questo piccolo amico ti seguirà durante le tue avventure su Azeroth e oltre.|n|nPuoi visualizzare tutte le tue mascotte cliccando sul pulsante |cffffd200Collezioni|r e guardando nella scheda |cffffd200Mascotte|r.", 0xe53f8fb8, "." },
  ["TUTORIAL_HUD_REVAMP_BAG_CHANGES"] = { "Clicca sull'icona per rivedere i nuovi filtri e le opzioni di combinazione della borsa.", 0x816f918e, "." },
  ["TUTORIAL_HUD_REVAMP_LFG_QUEUE_CHANGES"] = { "Sei in coda per un'attività.\n\nLe informazioni della coda della Ricerca gruppi appaiono qui.", 0x7d6058bc, "." },
  ["TUTORIAL_REAGENT_BAG_STEP_1"] = { "Hai ottenuto una Borsa dei Reagenti!|n|nApri la borsa.", 0x9a0fb64c, "." },
  ["TUTORIAL_REAGENT_BAG_STEP_2"] = { "Equipaggia la nuova Borsa dei Reagenti!|n|nI materiali d'artigianato raccolti andranno in questa borsa.", 0x85f5c0da, "." },
  ["TUTORIAL_SUPERTRACK_STEP_1"] = { "Concentrati su una missione cliccandone l'icona", 0x38d5cc67, "." },
